"""Materialize an audited source patch on the isolated R24 branch only.

The patch is a compressed git diff, not executable bytecode. Verify its digest,
check git applicability, then apply it. The CI workflow commits the resulting
readable sources before compiling/testing them. No main updates are allowed.
"""
from pathlib import Path
import base64
import hashlib
import subprocess
import zlib

EXPECTED = 'ca02dded5f6f74067502b0185925d8ae3d33a24619c3ca8fbaaca3fae98f6297'
PATCH = ''''''


def main():
    root = Path(__file__).resolve().parents[1]
    marker = root / '.studio-r24-applied'
    if marker.exists():
        if marker.read_text().strip() != EXPECTED:
            raise RuntimeError('A different R24 patch was applied; reconcile first.')
        return
    branch = subprocess.check_output(['git', 'branch', '--show-current'], cwd=root, text=True).strip()
    if branch != 'fix/studio-0624-flight-appearance-native':
        raise RuntimeError('Refusing to mutate a different branch.')
    patch = zlib.decompress(base64.b64decode(PATCH, validate=True))
    if hashlib.sha256(patch).hexdigest() != EXPECTED:
        raise RuntimeError('Patch integrity mismatch.')
    subprocess.run(['git', 'apply', '--check', '-'], input=patch, cwd=root, check=True)
    subprocess.run(['git', 'apply', '-'], input=patch, cwd=root, check=True)
    marker.write_text(EXPECTED + '\n')


if __name__ == '__main__':
    main()
